// Real product catalog (generated by `npm run catalog:build`):
//  - IKEA Indonesia products with official name, photo, price, SKU and stock status
//    (schema.org data from ikea.co.id product pages, see scripts/build-catalog.js)
//  - Tokopedia/Shopee listings found by Meta web search (verified URLs, no price)
import data from './realCatalog.json' with { type: 'json' }
import { detectTerms, norm } from './terms.js'
import { referencePrice } from '../lib/roomLayout.js'

export const CATALOG_META = { fetchedAt: data.fetchedAt, sources: data.sources }
export const CATALOG = (data.products || []).map(p => ({
  ...p,
  priceSource: p.priceIDR ? 'store' : 'estimate',
}))
const BY_ID = new Map(CATALOG.map(p => [p.id, p]))

export function productById(id) { return BY_ID.get(id) || null }

export function productTitle(p) { return p?.title || p?.name || '' }

// Price used in budgets: the store price when known, otherwise a reference estimate.
export function productPrice(p, style) {
  return p?.priceIDR || referencePrice(p?.archetype, style)
}

function score(p, { room, style, budgetPerItem }) {
  let s = 0
  if (p.styles?.includes(style)) s += 4 - p.styles.indexOf(style) * 0.5
  if (p.rooms?.includes(room)) s += 2
  if (p.availability === 'InStock') s += 1
  if (p.priceIDR) s += 0.5
  if (budgetPerItem && p.priceIDR) s -= Math.max(0, p.priceIDR / budgetPerItem - 1) * 2
  return s
}

export function searchCatalog({ room = 'living', style = 'Japandi', q = '', archetype = 'all', limit = 24 } = {}) {
  const { archetypes, styles } = detectTerms(q)
  const wantStyle = [...styles][0] || style
  let list
  let matchedQuery = true
  if (archetypes.size) {
    list = CATALOG.filter(p => archetypes.has(p.archetype))
  } else if (q.trim()) {
    const words = norm(q).trim().split(' ').filter(w => w.length > 2)
    list = CATALOG.filter(p => words.some(w => norm(p.title).includes(` ${w}`)))
    if (!list.length) { list = CATALOG.filter(p => p.rooms?.includes(room)); matchedQuery = false }
  } else {
    list = CATALOG.filter(p => p.rooms?.includes(room))
  }
  if (archetype !== 'all') list = list.filter(p => p.archetype === archetype)
  const ranked = list
    .map(p => ({ p, s: score(p, { room, style: wantStyle }) }))
    .sort((a, b) => b.s - a.s || (a.p.priceIDR || 9e9) - (b.p.priceIDR || 9e9))
    .map(x => x.p)
  return { products: ranked.slice(0, limit), total: ranked.length, matchedQuery }
}

export function rankProducts(archetype, { room, style, budgetPerItem, exclude = [] } = {}) {
  return CATALOG
    .filter(p => p.archetype === archetype && !exclude.includes(p.id))
    .map(p => ({ p, s: score(p, { room, style, budgetPerItem }) + (p.rooms?.includes(room) ? 0 : -3) }))
    .sort((a, b) => b.s - a.s)
    .map(x => x.p)
}

export function bestProductFor(archetype, style, room, opts = {}) {
  return rankProducts(archetype, { room, style, ...opts })[0] || null
}

// Shortlist of real products per furniture type, sent to Muse Spark so the
// design is built from things that can actually be bought.
export function candidatesFor({ room, style, archetypes, perType = 6, budgetIDR }) {
  const budgetPerItem = budgetIDR ? budgetIDR / Math.max(4, archetypes.length) : undefined
  const out = []
  for (const a of archetypes) {
    const ranked = rankProducts(a, { room, style, budgetPerItem })
    // keep a spread of prices: best matches first, then the cheapest alternatives
    const picks = [...ranked.slice(0, perType - 2), ...[...ranked].filter(p => p.priceIDR).sort((x, y) => x.priceIDR - y.priceIDR).slice(0, 2)]
    const seen = new Set()
    for (const p of picks) {
      if (seen.has(p.id)) continue
      seen.add(p.id)
      out.push({ id: p.id, type: a, name: p.title, priceIDR: p.priceIDR || null, size: p.size || null, store: p.store, styles: p.styles })
    }
  }
  return out
}
